mapper.select:
SELECT E.IDX AS EXTRACT_IDX, E.FILE_NAME, E.ZIP_ENTRY_FILE_NAME, E.RC_RFILE_NO, E.RC_RITEM_NO, E.ZIP_SEQ, E.FILE_TYPE, E.FILE_GUBUN, E.INDEXING_CONTENTS, E.HWP_SUB_TITLE, E.DATA_YEAR FROM EXTRACT_ELEC_DOC E WHERE E.EXTRACT_STATUS = 'PASS' AND E.INDEXING_CONTENTS IS NOT NULL AND TRIM(E.INDEXING_CONTENTS) != ''
AND E.DATA_YEAR = #{dataYear}
AND EXISTS ( SELECT 1 FROM CN_ELEC_DOC C WHERE C.TRANSFERYEAR = #{transferYear} AND C.RC_RFILE_NO = E.RC_RFILE_NO AND C.RC_RITEM_NO = E.RC_RITEM_NO )
AND NOT EXISTS ( SELECT 1 FROM TB_RECORD_CONTENT_CHUNK C WHERE C.EXTRACT_IDX = E.IDX )
ORDER BY E.RC_RFILE_NO, E.RC_RITEM_NO, E.FILE_NAME, E.ZIP_SEQ LIMIT #{limit} OFFSET #{offset}
